package com.example.attendanceapp.data.dto.response.staff;import androidx.annotation.Nullable;import com.google.gson.annotations.SerializedName;public class StaffCompanyResponse {    @SerializedName(value = "name_company", alternate = {"company_name", "companyName", "company"})    private String companyName;    @SerializedName(value = "name_manager", alternate = {"manager_name", "managerName"})    private String managerName;    @Nullable    @SerializedName(value = "position_staff", alternate = {"position", "staff_position"})    private String positionStaff;    @SerializedName(value = "id_manager", alternate = {"manager_id", "managerId", "idManager"})    private String managerId;    public StaffCompanyResponse() {}    public StaffCompanyResponse(String companyName, String managerName, String positionStaff, String managerId) {        this.companyName = companyName;        this.managerName = managerName;        this.positionStaff = positionStaff;        this.managerId = managerId;    }    public String getCompanyName() {        return companyName;    }    public void setCompanyName(String companyName) {        this.companyName = companyName;    }    public String getManagerName() {        return managerName;    }    public void setManagerName(String managerName) {        this.managerName = managerName;    }    @Nullable    public String getPositionStaff() {        return positionStaff;    }    public void setPositionStaff(@Nullable String positionStaff) {        this.positionStaff = positionStaff;    }    public String getManagerId() {        return managerId;    }    public void setManagerId(String managerId) {        this.managerId = managerId;    }}